package dev.workshopvideo;
import org.json.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;import java.awt.image.BufferedImage;import javax.imageio.ImageIO;import dev.workshopvideo.core.*;
public class ContentHostChecks {
 static int checks;static Path root;static byte[] png;static File file;
 static void check(boolean ok,String title){if(!ok)throw new AssertionError(title);checks++;}static void reject(Action action,String title)throws Exception{boolean rejected=false;try{action.run();}catch(Exception expected){rejected=true;}check(rejected,title);}interface Action{void run()throws Exception;}
 static void zip(JSONObject scene,boolean own)throws Exception {try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(file))){zip.putNextEntry(new ZipEntry(own?"wallpaper-mobile.json":"scene.json"));zip.write(scene.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));zip.closeEntry();zip.putNextEntry(new ZipEntry("bg.png"));zip.write(png);zip.closeEntry();}}
 static JSONObject scene()throws Exception{return new JSONObject().put("format","WallpaperMobileScene/1").put("width",1080).put("height",2400).put("effects",new JSONObject().put("gyro",true)).put("layers",new JSONArray().put(new JSONObject().put("file","bg.png").put("depth",.3)).put(new JSONObject().put("file","bg.png").put("depth",1.5).put("opacity",.5)));}
 static void adapterFixture(JSONObject root,byte[] png)throws Exception {try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(file))){Map<String,byte[]> entries=new LinkedHashMap<>();entries.put("scene.json",root.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));entries.put("model.json","{\"material\":\"material.json\"}".getBytes());entries.put("material.json","{\"passes\":[{\"shader\":\"genericimage4\",\"textures\":[\"bg.png\"]}]}".getBytes());entries.put("bg.png",png);for(var e:entries.entrySet()){zip.putNextEntry(new ZipEntry(e.getKey()));zip.write(e.getValue());zip.closeEntry();}}}
 public static void main(String[] args)throws Exception{
  root=Path.of(args[0]);Files.createDirectories(root);file=root.resolve("scene.mpkg").toFile();BufferedImage img=new BufferedImage(2,2,BufferedImage.TYPE_INT_ARGB);img.setRGB(0,0,0xffff0000);ByteArrayOutputStream bytes=new ByteArrayOutputStream();ImageIO.write(img,"png",bytes);png=bytes.toByteArray();
  JSONObject scene=scene();zip(scene,true);try(WallpaperContent.Scene s=WallpaperContent.scene(file)){check(s.layers.size()==2,"actual scene loader reads multiple layers");check(s.width==1080&&s.height==2400,"scene projection preserved");check(Math.abs(s.layers.get(1).depth-1.5)<.001,"layer parallax depth preserved");check(s.layers.get(1).alpha==.5f,"layer opacity preserved");check(s.layers.get(0).bitmap.getWidth()==2,"real layer image decoded");check(s.defaults.optBoolean("gyro"),"scene effect defaults read");}
  scene.getJSONArray("layers").getJSONObject(0).put("file","../escape");zip(scene,true);reject(()->WallpaperContent.scene(file),"scene file path traversal rejected");
  scene=scene();scene.put("width",1000000);zip(scene,true);reject(()->WallpaperContent.scene(file),"oversized scene projection rejected");
  scene=scene();scene.put("script","doSomething()");zip(scene,true);reject(()->WallpaperContent.scene(file),"script cannot be silently rendered as a static substitute");
  scene=scene();scene.getJSONArray("layers").getJSONObject(0).put("file","missing.png");zip(scene,true);reject(()->WallpaperContent.scene(file),"missing layer does not fall back to preview image");
  JSONObject we=new JSONObject().put("objects",new JSONArray().put(new JSONObject().put("image","model.json").put("origin","540 1200 0").put("size","1080 2400").put("scale","1 1 1").put("parallaxDepth",".5 .5")));
  try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(file))){Map<String,byte[]> data=new LinkedHashMap<>();data.put("scene.json",we.toString().getBytes());data.put("model.json","{\"material\":\"material.json\"}".getBytes());data.put("material.json","{\"passes\":[{\"shader\":\"genericimage2\",\"textures\":[\"bg.png\"]}]}".getBytes());data.put("bg.png",png);for(var e:data.entrySet()){zip.putNextEntry(new ZipEntry(e.getKey()));zip.write(e.getValue());zip.closeEntry();}}
  try(WallpaperContent.Scene s=WallpaperContent.scene(file)){check(s.layers.size()==1&&s.layers.get(0).x==0&&s.layers.get(0).y==0,"basic WE image material and coordinate mapping");}
  we.getJSONArray("objects").getJSONObject(0).put("particle","particle.json");zip(we,false);reject(()->WallpaperContent.scene(file),"unsupported WE particles are explicit incompatibility");
  // Explicit adapter snapshots actual base textures; unrelated author effects are never silently called supported.
  JSONObject imageObject=new JSONObject().put("image","model.json").put("origin","540 1200 0").put("size","1080 2400").put("angles","0 0 1.57079632679").put("effects",new JSONArray().put(new JSONObject().put("file","effects/waterflow/effect.json")));
  JSONObject authored=new JSONObject().put("general",new JSONObject().put("orthogonalprojection",new JSONObject().put("width",1080).put("height",2400))).put("objects",new JSONArray().put(imageObject).put(new JSONObject().put("particle","fog.json")));
  adapterFixture(authored,png);byte[] before=Files.readAllBytes(file.toPath());
  try(ContentArchive a=new ContentArchive(file)){SceneAdapter.Report report=SceneAdapter.inspect(a);try{check(report.usable()&&report.scene.layers.size()==1&&report.particles==1,"adapter reports real decoded image and omitted particle");check(report.effects.contains("waterflow"),"adapter identifies dropped author effect");check(Math.abs(report.scene.layers.get(0).rotation+90)<.01,"WE radians and bottom-up rotation map to Android degrees");File converted=root.resolve("adapted.zip").toFile();SceneAdapter.write(report,converted);try(WallpaperContent.Scene loaded=WallpaperContent.scene(converted)){check(loaded.layers.size()==1&&loaded.layers.get(0).bitmap.getWidth()==2,"adapted image-layer package passes production renderer parser");File mobileCopy=root.resolve("mobile-copy.zip").toFile();File mobileWork=root.resolve("mobile-work").toFile();mobileWork.mkdirs();SceneDownload.Prepared own=SceneDownload.prepare(converted,mobileCopy,mobileWork,()->{});check(!own.adapted()&&own.kind().equals("scene"),"existing mobile-format package is validated without another adaptation");}check(Arrays.equals(before,Files.readAllBytes(file.toPath())),"conversion never modifies original package");}finally{report.scene.close();}}
  imageObject.put("parent",10);adapterFixture(authored,png);try(ContentArchive a=new ContentArchive(file)){SceneAdapter.Report report=SceneAdapter.inspect(a);try{check(!report.usable()&&report.scene.layers.isEmpty(),"unsupported parent transform cannot create an eligible wallpaper");}finally{report.scene.close();}}
  imageObject.remove("parent");imageObject.put("visible",new JSONObject().put("user","toggle").put("value",false));adapterFixture(authored,png);try(ContentArchive a=new ContentArchive(file)){SceneAdapter.Report report=SceneAdapter.inspect(a);try{check(!report.usable()&&report.bindings==1,"author default hidden state is respected");}finally{report.scene.close();}}
  imageObject.put("visible",true);imageObject.put("scale","-1 1 1");adapterFixture(authored,png);try(ContentArchive a=new ContentArchive(file)){SceneAdapter.Report report=SceneAdapter.inspect(a);try{check(!report.usable(),"unsupported mirrored transform cannot masquerade as exact composition");}finally{report.scene.close();}}
  JSONObject normalized=EffectOptions.normalize(new JSONObject().put("zoom",900).put("speed",.01).put("fps",1000).put("gyro",true).put("depth1",8).put("opacity1",-1));
  check(normalized.getDouble("zoom")==2.5,"zoom budget capped");check(normalized.getDouble("speed")==.25,"playback speed lower bound");check(normalized.getDouble("fps")==60,"drawing FPS capped");check(normalized.getBoolean("gyro"),"sensor toggle survives normalization");check(normalized.getDouble("depth1")==2&&normalized.getDouble("opacity1")==0,"per-layer values bounded");
  JSONObject restored=EffectOptions.normalize(new JSONObject(normalized.toString()));check(restored.toString().equals(normalized.toString()),"effect settings stable across persistence round trip");
  float[] v=WallpaperContent.vector(new JSONObject().put("value","12 34 56"),0,0,0);check(v[1]==34,"WE wrapped vector value parsed");
  Files.write(root.resolve("image.bin"),png);check(WallpaperContent.kind(root.resolve("image.bin").toFile()).equals("image"),"file kind determined from contents rather than suffix");
  try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(file))){zip.putNextEntry(new ZipEntry("project.json"));zip.write("{\"type\":\"image\",\"file\":\"picture.png\"}".getBytes());zip.closeEntry();zip.putNextEntry(new ZipEntry("picture.png"));zip.write(png);zip.closeEntry();}try(ContentArchive a=new ContentArchive(file)){check(WallpaperContent.mediaEntry(a).equals("picture.png"),"mpkg media selection follows manifest rather than arbitrary preview");check(Arrays.equals(a.read(WallpaperContent.mediaEntry(a),10000),png),"manifest-selected media preserves original bytes");}
  scene=scene();scene.getJSONArray("layers").getJSONObject(0).put("opacity",new JSONObject().put("user","opacity"));zip(scene,true);reject(()->WallpaperContent.scene(file),"unimplemented author property binding is reported explicitly");
  if(args.length>1)try(WallpaperContent.Scene demo=WallpaperContent.scene(new File(args[1]))){check(demo.layers.size()==3,"shipping demo loads three actual layers");check(demo.layers.get(0).depth==0&&demo.layers.get(2).depth==1.5f,"shipping demo retains distinct depths");check(demo.defaults.optBoolean("gyro")&&demo.defaults.optBoolean("ripple"),"shipping demo exercises real sensor and touch switches");}
  WorkshopFlowChecks.run(root,png);
  System.out.println("PASS: "+checks+" production content/scene/settings checks with desktop image fixtures; not an Android UI test");
 }
}